WITH filtered_accounts AS (SELECT * FROM accounts WHERE customer_id IS NOT NULL AND account_type IN ('CHECKING', 'CREDIT', 'SAVINGS') AND status <> 'FROZEN'), agg AS (SELECT account_type, status, MAX(opened_date) AS latest_opened_date, SUM(balance) AS total_balance FROM filtered_accounts GROUP BY account_type, status) SELECT account_type, status, latest_opened_date, total_balance FROM agg ORDER BY account_type;
